qualified_questions.sparql_query:
PREFIX VideoGameOntology: <http://example.org/VideoGameOntology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?player (COUNT(DISTINCT ?game) AS ?numberOfGames) (COUNT(DISTINCT ?achievement) AS ?numberOfAchievements)
WHERE {
    ?player rdf:type VideoGameOntology:Player.
    OPTIONAL { ?player VideoGameOntology:playsGame ?game. }
    OPTIONAL { ?player VideoGameOntology:ownsAchievement ?achievement. }
}
GROUP BY ?player
ORDER BY ?numberOfGames ?numberOfAchievements

PREFIX VideoGameOntology: <http://example.org/VideoGameOntology/>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX dcterms: <http://purl.org/dc/terms/>

SELECT ?player (COUNT(DISTINCT ?friend) AS ?numFriends) (COUNT(DISTINCT ?achievement) AS ?numAchievements)
WHERE {
    ?player rdf:type VideoGameOntology:Player.
    OPTIONAL { 
        ?player VideoGameOntology:isFriendWithPlayer ?friend .
    }
    OPTIONAL { 
        ?player VideoGameOntology:ownsAchievement ?achievement .
    }
}
GROUP BY ?player
ORDER BY ?numFriends ?numAchievements

PREFIX VideoGameOntology: <http://video-game-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?achievement 
WHERE {
    ?achievement rdf:type VideoGameOntology:Achievement .
    VALUES ?achievement { VideoGameOntology:Loyalty VideoGameOntology:Paragon VideoGameOntology:Completion VideoGameOntology:SpecialPlayStyle VideoGameOntology:Luck VideoGameOntology:Minigame VideoGameOntology:HardMode VideoGameOntology:Curiosity VideoGameOntology:Virtuosity VideoGameOntology:Multiplayer VideoGameOntology:Fandom VideoGameOntology:Collection VideoGameOntology:Veteran VideoGameOntology:Tutorial }
}

PREFIX VideoGameOntology: <http://video_game_ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?player
WHERE {
    ?player rdf:type VideoGameOntology:Player .
    OPTIONAL { 
        ?achievement rdf:type VideoGameOntology:Virtuosity .
        ?player VideoGameOntology:hasAchievement ?achievement .
    }
}

PREFIX VideoGameOntology: <http://video-game-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?x
WHERE {
    ?x rdf:type VideoGameOntology:Achievement .
    ?game rdf:type VideoGameOntology:GameProduct .
    FILTER NOT EXISTS { 
        ?x VideoGameOntology:purchasesGameOffering ?game .
    }
}

PREFIX VideoGameOntology: <http://video-game-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?achievement
WHERE {
    ?tutorial rdf:type VideoGameOntology:Tutorial .
    ?achievement rdf:type VideoGameOntology:Achievement .
    FILTER EXISTS { 
        ?tutorial rdfs:subClassOf ?mid .
        ?mid rdfs:subClassOf* ?achievement 
    }
}

PREFIX VideoGameOntology: <http://video-game-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?event ?description
WHERE {
    ?event rdf:type VideoGameOntology:InstantaneousEvent .
    OPTIONAL { ?event rdfs:comment ?description . }
    FILTER(EXISTS { ?event rdf:type VideoGameOntology:InAppPurchaseEvent })
}

PREFIX VideoGameOntology: <http://example.org/VideoGameOntology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?achievement
WHERE {
    ?event rdf:type VideoGameOntology:InstantaneousEvent .
    ?event VideoGameOntology:isEventInSession ?session .
    ?player rdf:type VideoGameOntology:Player .
    ?player VideoGameOntology:username ?username .
    ?event VideoGameOntology:unlocksAchievement ?achievement .
    {
        SELECT ?session
        WHERE {
            ?event2 rdf:type VideoGameOntology:InstantaneousEvent .
            ?event2 VideoGameOntology:isEventInSession ?session .
        }
        GROUP BY ?session
        HAVING (COUNT(DISTINCT ?event2) > 1)
    }
    FILTER EXISTS { 
        ?player VideoGameOntology:username ?username .
        ?event VideoGameOntology:isEventInSession ?session .
    }
}

PREFIX net: <http://www.example.net/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?user ?purpose
WHERE {
    net:VideoGameOntology rdf:type owl:Ontology .
    OPTIONAL { 
        ?user rdfs:comment ?commentUser .
        FILTER regex(?commentUser, "might use", "i") .
    }
    OPTIONAL { 
        ?purpose rdfs:comment ?commentPurpose .
        FILTER regex(?commentPurpose, "for what purposes", "i") .
    }
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
SELECT ?creator
WHERE {
    ?game dc:contributor ?creator .
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
SELECT ?information
WHERE {
    ?game dc:creator ?creator .
    OPTIONAL { ?game dc:description ?information . }
    BIND(EXISTS { ?game dc:description ?information } AS ?hasDescription)
    FILTER(?hasDescription)
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?game
WHERE {
    ?game rdf:type ?type .
    FILTER NOT EXISTS { ?game dc:creator [] }
    FILTER NOT EXISTS { ?game dc:contributor [] }
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?creator ?game ?influence
WHERE {
    ?game dc:creator ?creator .
    ?creator rdf:type ?type .
    OPTIONAL { 
        ?creator rdfs:comment ?influence . 
        FILTER(regex(?influence, "experience", "i"))
    }
}

PREFIX game: <http://example.org/game/>
PREFIX behavior: <http://example.org/behavior/>
PREFIX engagement: <http://example.org/engagement/>

SELECT ?genre ?behaviorType ?engagementLevel
WHERE {
    ?game a game:Game .
    ?game game:hasGenre ?genre .
    OPTIONAL { 
        ?game behavior:affectsBehavior ?behaviorType . 
    }
    OPTIONAL { 
        ?game engagement:influencesEngagement ?engagementLevel . 
    }
}
